        elif c == 'R':
            R += 1
        elif c == 'U':
            U += 1
        else:
            D += 1

    min_moves = float('inf')
    for l in range(L + 1):
        r = L - l
        u = (L + R) // 2 - l
        d = (L + R) // 2 - r
        if u < 0 or d < 0:
